      "Показатели дивизиона Р. стабильно в топ-2 по сети три года подряд. С 2023 года компания начала массовый найм на аналитические позиции выпускников программ MBA и профильных цифровых магистратур – для перехода на закупки и планирование ассортимента, основанные на данных, а не на опыте закупщиков. За последний год у Р. произошло три задокументированных конфликта с новыми аналитиками её дивизиона: она публично на совещании назвала одну из рекомендаций «цифрами без понимания жизни», дважды отменяла внедрение предложенных аналитиками изменений в графике закупок без объяснения причин.",
