    "accent": "#2d5a7b",
    "summary": "Закрытие 40% отделений банка и перевод операционистов в цифровые консультанты. Люди боятся потерять статус 'уважаемого сотрудника у стойки' и провалиться в онлайне.",
    "facts": [
      "Банк «DL» – розничное и малое корпоративное кредитование, 210 отделений в регионах России, на рынке 21 год. С 2023 года банк последовательно сокращает число физических отделений (закрыто 38 за полтора года) в пользу цифровых каналов обслуживания. Сотрудники закрываемых отделений частично переводятся на позиции, связанные с сопровождением цифровых сервисов и удалённой работой с клиентами. Внутренний опрос переведённых сотрудников показывает: 61% оценивают свою готовность к новой работе как низкую, при этом формальное обучение (онлайн-курсы по новым системам) пройдено практически всеми – проблема не в отсутствии инструкций, а в неуверенности в применении новых навыков в реальном общении с клиентами. В комментариях к опросу неоднократно встречается формулировка: «я двадцать лет умел разговаривать с человеком через стойку, а теперь не понимаю, тот ли я специалист, каким был». Банк уже располагает данными по первой волне перевода (14 отделений, переведено 9 месяцев назад), что даёт возможность сравнения, а не только прогноза. Результаты неоднородны: 58% из переведённых в первой волне сейчас (спустя 9 месяцев) демонстрируют показатели работы на уровне или выше среднего по новому формату; 27% – устойчиво ниже среднего, без признаков улучшения за последние три месяца; 15% уволились в течение первого полугодия после перевода.",
      "При сопоставлении с возрастом и стажем обнаруживается частичная, но не абсолютная закономерность: среди уволившихся и «застрявших» на низких показателях преобладают сотрудники со стажем очной работы свыше 15 лет – но не все такие сотрудники попали в эту категорию: примерно треть сотрудников с таким же стажем успешно адаптировалась и входит в группу с показателями выше среднего. Единственное дополнительное различие, которое находит HR при повторных интервью: успешно адаптировавшиеся «ветераны», в отличие от неуспешных, в разговоре описывают свою прежнюю работу через набор переносимых навыков («я умею слушать человека и вести его через сложный разговор»), а не только через конкретный формат («я работал у стойки») – то есть разница не в стаже как таковом, а в том, как человек сам для себя определяет суть своей профессии."
    ],
