      "Розничная сеть косметики «JC» – до 2022 года франчайзинговая сеть международного бренда, 140 магазинов в России. После ухода бренда с российского рынка в 2022 году сеть была выкуплена собственным менеджментом компании (такая сделка называется management buyout – выкуп бизнеса его же руководством), сменились название, часть ассортимента, вся система поставок (переход на новых поставщиков из Азии и параллельный импорт части прежних марок).",
