      "Т. (36 лет, замужем, двое детей, младшему – год) вернулась из отпуска по уходу за ребёнком (14 месяцев) на позицию старшего менеджера по работе с ключевыми клиентами. До ухода в отпуск Т. была в кадровом резерве на позицию руководителя направления – считалась одной из сильнейших кандидаток, с наивысшим рейтингом по итогам последней аттестации перед декретом. За два месяца после возвращения все количественные показатели (объём портфеля, конверсия встреч, число повторных сделок) восстановились до прежнего уровня, а по качеству повторных продаж – даже превысили его.",
